function Transfer() {
  const { toast } = useContext(ToastContext)!;
  const [step, setStep] = useState(1);
  const [beneficiary, setBeneficiary] = useState('Aarav Mehta · HDFC Bank');
  const [transferAmount, setTransferAmount] = useState('3500');
  const [note, setNote] = useState('Dinner split');
  const [done, setDone] = useState(false);
  const next = () => { if (step < 3) setStep((value) => value + 1); else { setDone(true); toast('Transfer simulated', '₹3,500 receipt is ready. No funds were moved.'); } };
  return <main className="content page-enter"><PageHeading eyebrow="Move money" title="Transfer, without the guesswork." description="A clear three-step flow with a final pause before anything happens." action={<span className="badge amber"><Shield size={12} />Prototype action</span>} /><div className="card card-pad" style={{ maxWidth: 780, margin: '0 auto' }}>{done ? <div className="receipt" style={{ textAlign: 'center' }}><CheckCircle2 size={43} color="hsl(145 53% 38%)" /><div className="eyebrow" style={{ marginTop: 15 }}>Demo complete</div><h2 className="display" style={{ margin: '8px 0', fontSize: '2rem' }}>Transfer queued.</h2><p className="text-dim" style={{ fontSize: '.75rem' }}>In a real account, ₹{Number(transferAmount).toLocaleString('en-IN')} would be sent to {beneficiary.split(' · ')[0]}.</p><div className="receipt-code">NXR-DEMO-240618-7Q</div><div className="form-actions" style={{ justifyContent: 'center' }}><button className="btn btn-ghost" onClick={() => { setDone(false); setStep(1); }} data-testid="button-new-transfer">New demo transfer</button><button className="btn btn-accent" onClick={() => toast('Receipt downloaded', 'A local demo receipt was prepared.')} data-testid="button-download-receipt"><Download size={14} />Download receipt</button></div></div> : <><div className="steps">{['Beneficiary', 'Amount', 'Review'].map((label, index) => <div className="step-wrap" key={label} style={{ display: 'contents' }}><div className={`step ${step >= index + 1 ? 'active' : ''}`}><span>{step > index + 1 ? <Check size={13} /> : index + 1}</span>{label}</div>{index < 2 && <div className="step-line" />}</div>)}</div>{step === 1 && <div><div className="card-header"><div><h2 className="section-title">Who are you sending to?</h2><p className="section-kicker">Only demo beneficiaries are available.</p></div><UserRound size={20} color="hsl(var(--accent))" /></div><div className="field"><label htmlFor="beneficiary">Saved beneficiary</label><select className="select" id="beneficiary" value={beneficiary} onChange={(event) => setBeneficiary(event.target.value)} data-testid="select-beneficiary"><option>Aarav Mehta · HDFC Bank</option><option>Riya Shah · ICICI Bank</option><option>Self · NEXORA savings</option></select></div><div className="receipt" style={{ marginTop: 20 }}><div className="eyebrow">Protected flow</div><p style={{ margin: '8px 0 0', fontSize: '.7rem' }}>You will review the recipient, amount and note before this prototype shows a confirmation.</p></div></div>}{step === 2 && <div><div className="card-header"><div><h2 className="section-title">How much?</h2><p className="section-kicker">Available balance · ₹1,84,620</p></div><IndianRupee size={20} color="hsl(var(--accent))" /></div><div className="field"><label htmlFor="transfer-amount">Amount in INR</label><div className="input-with-icon"><IndianRupee size={15} /><input className="input" id="transfer-amount" type="number" min="1" value={transferAmount} onChange={(event) => setTransferAmount(event.target.value)} data-testid="input-transfer-amount" /></div></div><div className="field" style={{ marginTop: 17 }}><label htmlFor="transfer-note">Add a note</label><input className="input" id="transfer-note" value={note} onChange={(event) => setNote(event.target.value)} data-testid="input-transfer-note" /></div></div>}{step === 3 && <div><div className="card-header"><div><h2 className="section-title">Review before you send</h2><p className="section-kicker">This is the final step in the demo.</p></div><Shield size={20} color="hsl(var(--accent))" /></div><div className="receipt"><div className="control-row"><span>To</span><strong>{beneficiary}</strong></div><div className="control-row"><span>Amount</span><strong>{currency(Number(transferAmount) || 0)}</strong></div><div className="control-row"><span>Note</span><strong>{note || '—'}</strong></div><div className="control-row"><span>Fee</span><strong style={{ color: 'hsl(145 53% 38%)' }}>₹0 · demo</strong></div></div></div>}<div className="form-actions">{step > 1 && <button className="btn btn-ghost" onClick={() => setStep((value) => value - 1)} data-testid="button-back-transfer">Back</button>}<button className="btn btn-accent" onClick={next} data-testid="button-next-transfer">{step === 3 ? 'Confirm demo transfer' : 'Continue'} <ArrowRight size={14} /></button></div></>}</div></main>;
}

