function Loans() {
  const [principal, setPrincipal] = useState('350000');
  const [months, setMonths] = useState('24');
  const [rate, setRate] = useState('12.5');
  const monthly = (Number(principal) * (Number(rate) / 1200) * Math.pow(1 + Number(rate) / 1200, Number(months))) / (Math.pow(1 + Number(rate) / 1200, Number(months)) - 1) || 0;
  return <main className="content page-enter"><PageHeading eyebrow="Borrow with clarity" title="A loan should feel legible." description="Explore demo offers and see the repayment shape before committing." action={<span className="badge amber"><LockKeyhole size={12} />No credit check</span>} /><section className="grid-3"><div className="card loan-card"><div className="eyebrow">Flexible personal</div><h3>Up to ₹8,00,000</h3><p>For a course, a move, or the plan you have been quietly building.</p><div className="badge amber" style={{ marginTop: 22 }}>From 11.4% p.a.</div></div><div className="card loan-card" style={{ background: 'linear-gradient(135deg, hsl(38 74% 36%), hsl(20 63% 34%))' }}><div className="eyebrow">Education boost</div><h3>Up to ₹15,00,000</h3><p>A flexible bridge for tuition, equipment and new beginnings.</p><div className="badge amber" style={{ marginTop: 22 }}>From 10.9% p.a.</div></div><div className="card loan-card" style={{ background: 'linear-gradient(135deg, hsl(224 37% 26%), hsl(260 25% 29%))' }}><div className="eyebrow">Smart top-up</div><h3>Already with us?</h3><p>See a personalised demo offer built around your existing relationship.</p><div className="badge amber" style={{ marginTop: 22 }}>Check eligibility</div></div></section><section className="grid-2" style={{ marginTop: 18 }}><div className="card card-pad"><div className="card-header"><div><div className="section-title">EMI calculator</div><div className="section-kicker">Adjust the dials. Find your comfort zone.</div></div><Calculator size={18} color="hsl(var(--accent))" /></div><div className="form-grid"><div className="field"><label htmlFor="loan-principal">Loan amount</label><input className="input" id="loan-principal" type="number" value={principal} onChange={(event) => setPrincipal(event.target.value)} data-testid="input-loan-amount" /></div><div className="field"><label htmlFor="loan-rate">Interest rate p.a.</label><input className="input" id="loan-rate" type="number" step=".1" value={rate} onChange={(event) => setRate(event.target.value)} data-testid="input-loan-rate" /></div><div className="field full"><label htmlFor="loan-months">Tenure · {months} months</label><input id="loan-months" type="range" min="6" max="60" value={months} onChange={(event) => setMonths(event.target.value)} style={{ accentColor: 'hsl(var(--accent))' }} data-testid="input-loan-tenure" /></div></div></div><div className="card card-pad"><div className="eyebrow">Estimated monthly EMI</div><div className="balance-value" style={{ color: 'hsl(var(--foreground))', margin: '14px 0 4px' }}>{currency(Math.round(monthly))}</div><p className="text-dim" style={{ fontSize: '.7rem' }}>for {months} months at {rate}% p.a.</p><div className="control-row" style={{ marginTop: 15 }}><span className="text-dim" style={{ fontSize: '.68rem' }}>Total interest</span><strong>{currency(Math.max(0, Math.round(monthly * Number(months) - Number(principal))))}</strong></div><div className="control-row"><span className="text-dim" style={{ fontSize: '.68rem' }}>Total repayment</span><strong>{currency(Math.round(monthly * Number(months)))}</strong></div><button className="btn btn-accent" style={{ marginTop: 18 }} onClick={() => window.alert('Demo only: no loan application was created.')} data-testid="button-explore-loan">Explore demo offer <ArrowRight size={14} /></button></div></section></main>;
}

