  const sendMessage = (event: FormEvent) => { event.preventDefault(); if (!message.trim()) return; const next = message.trim(); setMessage(''); setMessages((items) => [...items, { from: 'user', text: next }, { from: 'agent', text: next.toLowerCase().includes('card') ? 'You can freeze or unfreeze your virtual card in Cards & controls. I can take you there.' : 'I can help with demo transfers, cards, security or understanding your money map. Try asking about any of those.' }]); };
  return <main className="content page-enter"><PageHeading eyebrow="Always-on desk" title="Help, without the hold music." description="Search the guide or start a conversation with our simulated support desk." /><section className="grid-2"><div><div className="card card-pad"><div className="input-with-icon"><Search size={15} /><input className="input" placeholder="Search help articles" data-testid="input-support-search" /></div><div className="grid-2" style={{ marginTop: 16, gap: 9 }}><button className="category" data-testid="support-category-payments"><span className="category-icon"><Receipt size={15} /></span><span><strong>Payments</strong><span>Transfers and bills</span></span></button><button className="category" data-testid="support-category-cards"><span className="category-icon"><CreditCard size={15} /></span><span><strong>Cards</strong><span>Freeze and controls</span></span></button><button className="category" data-testid="support-category-security"><span className="category-icon"><Shield size={15} /></span><span><strong>Security</strong><span>Keep your account safe</span></span></button><button className="category" data-testid="support-category-account"><span className="category-icon"><UserRound size={15} /></span><span><strong>Account</strong><span>Profile and preferences</span></span></button></div></div><div className="card card-pad" style={{ marginTop: 16 }}><div className="section-title">Popular answers</div><div className="control-row"><span>How do I freeze my card?</span><ArrowRight size={14} /></div><div className="control-row"><span>Where can I see my receipt?</span><ArrowRight size={14} /></div><div className="control-row"><span>How does NOVA use my data?</span><ArrowRight size={14} /></div></div></div><div className="card card-pad chat"><div className="card-header"><div><div className="section-title">Chat with Mira</div><div className="section-kicker"><span className="badge success">Online</span> Replies instantly in demo mode</div></div><Bot size={20} color="hsl(var(--accent))" /></div><div className="chat-messages">{messages.map((item, index) => <div className={`bubble ${item.from === 'user' ? 'user' : ''}`} key={index}>{item.text}</div>)}</div><form className="chat-input" onSubmit={sendMessage}><input className="input" value={message} onChange={(event) => setMessage(event.target.value)} placeholder="Ask Mira anything" data-testid="input-support-chat" /><button className="btn btn-accent" aria-label="send support message" data-testid="button-send-support"><Send size={14} /></button></form></div></section></main>;
